mapper.select:
SELECT AREAKY
  FROM LOCMA A
 WHERE 1 = 1
   AND WAREKY = #{WAREKY}
   AND LOCAKY = #{LOCAKY}

SELECT AH.ASNDKY , AI.SEBELN , AI.STKNUM , AH.STATDO , NVL((SELECT CDESC1 FROM CMCDV WHERE CMCDKY = 'STATDO' AND CMCDVL = AH.STATDO),' ') AS STATDONM , AH.WAREKY , NVL((SELECT NAME01 FROM WAHMA WHERE WAREKY = AH.WAREKY),' ') AS WARENM , AH.OWNRKY , NVL((SELECT NAME01 FROM OWNER WHERE OWNRKY = AH.OWNRKY),' ') AS OWNRNM , AH.ASNTTY AS RCPTTY , NVL((SELECT SHORTX FROM DOCTM WHERE DOCUTY = AH.ASNTTY),' ') AS RCPTNM , AH.ASNDAT , TO_CHAR(SYSDATE,'YYYYMMDD') AS DOCDAT , AH.DPTNKY , NVL(VD.NAME01,'NOT EXISTS SELLER') AS DPTNNM , SM.SKUG05 AS SELLER , NVL(SL.NAME01,'NOT EXISTS SELLER') AS SELLERNM , CASE WHEN AH.ASNTTY = '121' THEN AH.DPTNKY ELSE ' ' END AS WAREFR , CASE WHEN AH.ASNTTY = '121' THEN NVL(VD.NAME01,'NOT EXISTS SELLER') ELSE ' ' END AS WAREFRNM , AH.CARTYP , AH.DELVCO , AH.VEHINO , AH.INSPTY , AH.DRELIN , CASE WHEN TRIM(AI.VEHDAT) IS NULL OR AI.VEHDAT = '00000000' THEN ' ' ELSE 'V' END AS UNLOAD , AH.DOCTXT , AI.INVCNO , AH.DELMAK , CASE WHEN EXISTS ( SELECT 1 FROM ASNDI AA WHERE AH.ASNDKY = AA.ASNDKY AND AA.STATIT IN ('FRV', 'PRV', 'ORV', 'ZRV') ) THEN 'V' ELSE ' ' END AS INDDCL FROM ASNDH AH INNER JOIN ASNDI AI ON AI.ASNDKY = AH.ASNDKY LEFT OUTER JOIN BZPTN VD ON VD.OWNRKY = AH.OWNRKY AND VD.PTNRKY = AH.DPTNKY AND VD.PTNRTY = 'VD' LEFT OUTER JOIN SKUMA SM ON SM.OWNRKY = AH.OWNRKY AND SM.SKUKEY = AI.SKUKEY LEFT OUTER JOIN BZPTN SL ON SL.OWNRKY = AH.OWNRKY AND SL.PTNRKY = SM.SKUG05 AND SL.PTNRTY = 'VD' LEFT OUTER JOIN SKUWC SW ON SW.WAREKY = AH.WAREKY AND SW.OWNRKY = AH.OWNRKY AND SW.SKUKEY = AI.SKUKEY LEFT OUTER JOIN MEASI MI ON MI.WAREKY = AH.WAREKY AND MI.MEASKY = SW.MEASKY AND MI.UOMKEY = SM.DUOMKY WHERE AH.WAREKY = #{WAREKY} AND AH.OWNRKY = #{OWNRKY} AND (AH.ASNTTY LIKE '11%' OR AH.ASNTTY LIKE '12%')
AND AH.ASNTTY = #{RCPTTY}
AND AH.DRELIN = #{DRELIN}
AND AH.DELMAK = #{DELMAK}
AND AI.STATIT IN ('FRV', 'PRV', 'ORV', 'ZRV')
AND TRIM(AH.DELMAK) IS NULL AND AI.INDDCL = ' '
${RANGE_SQL}
GROUP BY AH.ASNDKY , AI.SEBELN , AI.STKNUM , AI.VEHDAT , AH.STATDO , AH.WAREKY , AH.OWNRKY , AH.ASNTTY , AH.ASNDAT , AH.DPTNKY , NVL(VD.NAME01,'NOT EXISTS SELLER') , SM.SKUG05 , NVL(SL.NAME01,'NOT EXISTS SELLER') , CASE WHEN AH.ASNTTY = '121' THEN AH.DPTNKY ELSE ' ' END , CASE WHEN AH.ASNTTY = '121' THEN NVL(VD.NAME01,'NOT EXISTS SELLER') ELSE ' ' END , AH.CARTYP , AH.DELVCO , AH.VEHINO , AH.DOCTXT , VD.PTNRKY , TRIM(VD.PROCHA) , TRIM(VD.DELMAK) , AH.INSPTY , AH.DRELIN , AI.INVCNO , AH.DELMAK

SELECT AH.ASNDKY , AI.SEBELN , AI.STKNUM , AH.STATDO , NVL((SELECT CDESC1 FROM CMCDV WHERE CMCDKY = 'STATDO' AND CMCDVL = AH.STATDO),' ') AS STATDONM , AH.WAREKY , NVL((SELECT NAME01 FROM WAHMA WHERE WAREKY = AH.WAREKY),' ') AS WARENM , AH.OWNRKY , NVL((SELECT NAME01 FROM OWNER WHERE OWNRKY = AH.OWNRKY),' ') AS OWNRNM , AH.ASNTTY AS RCPTTY , NVL((SELECT SHORTX FROM DOCTM WHERE DOCUTY = AH.ASNTTY),' ') AS RCPTNM , AH.ASNDAT , TO_CHAR(SYSDATE,'YYYYMMDD') AS DOCDAT , AH.DPTNKY , NVL(VD.NAME01,'NOT EXISTS SELLER') AS DPTNNM , AH.CARTYP , AH.DELVCO , AH.VEHINO , AH.INSPTY , AH.DRELIN , CASE WHEN TRIM(AI.VEHDAT) IS NULL OR AI.VEHDAT = '00000000' THEN ' ' ELSE 'V' END AS UNLOAD , AH.DOCTXT , AH.DELMAK , AI.INVCNO , AH.CLMRSN , AH.DLVETY , AI.SVBELN , AI.SPOSNR , AI.STRAID , CASE WHEN VD.PTNRKY IS NULL THEN '존재하지 않는 SELLER 마스터 입니다.' WHEN TRIM(VD.PROCHA) IS NOT NULL THEN '입고불허된 SELLER 입니다.' WHEN TRIM(VD.DELMAK) IS NOT NULL THEN '마스터 삭제된 SELLER 입니다.' END RSTTXT FROM ASNDH AH INNER JOIN ASNDI AI ON AI.ASNDKY = AH.ASNDKY LEFT OUTER JOIN BZPTN VD ON VD.OWNRKY = AH.OWNRKY AND VD.PTNRKY = AH.DPTNKY AND VD.PTNRTY = 'VD' LEFT OUTER JOIN SKUMA SM ON SM.OWNRKY = AH.OWNRKY AND SM.SKUKEY = AI.SKUKEY LEFT OUTER JOIN SKUWC SW ON SW.WAREKY = AH.WAREKY AND SW.OWNRKY = AH.OWNRKY AND SW.SKUKEY = AI.SKUKEY LEFT OUTER JOIN MEASI MI ON MI.WAREKY = AH.WAREKY AND MI.MEASKY = SW.MEASKY AND MI.UOMKEY = SM.DUOMKY WHERE AH.WAREKY = #{WAREKY} AND AH.OWNRKY = #{OWNRKY} AND AH.ASNTTY LIKE '13%' AND TRIM(AH.DELMAK) IS NULL AND AI.QTYASN - AI.QTYRCV > 0 AND AI.STATIT IN ('NEW', 'RDY')
AND AH.DELMAK = #{DELMAK}
${RANGE_SQL}
GROUP BY AH.ASNDKY , AI.SEBELN , AI.STKNUM , AI.VEHDAT , AH.STATDO , AH.WAREKY , AH.OWNRKY , AH.ASNTTY , AH.ASNDAT , AH.DPTNKY , NVL(VD.NAME01,'NOT EXISTS SELLER') , AH.CARTYP , AH.DELVCO , AH.VEHINO , AH.DOCTXT , VD.PTNRKY , TRIM(VD.PROCHA) , TRIM(VD.DELMAK) , AH.INSPTY , AH.DRELIN , AH.DELMAK , AI.INVCNO , AH.CLMRSN , AH.DLVETY , AI.SVBELN , AI.SPOSNR , AI.STRAID

