mapper.select:
SELECT RI.REFDKY AS ASNDKY , RI.SEBELN AS SEBELN , RI.STKNUM AS STKNUM , RH.WAREKY AS WAREKY , NVL((SELECT NAME01 FROM WAHMA WH WHERE WH.WAREKY = RH.WAREKY), ' ') AS WAREKYNM , RH.OWNRKY AS OWNRKY , NVL((SELECT NAME01 FROM OWNER NM WHERE NM.COMPKY = RH.OWNRKY),' ') AS OWNRKYNM , RH.DPTNKY AS DPTNKY , NVL((SELECT NAME01 FROM BZPTN BZ WHERE BZ.OWNRKY = RH.OWNRKY AND BZ.PTNRKY = RH.DPTNKY AND BZ.PTNRTY ='VD'), ' ') AS DPTNKYNM , RH.RCPTTY AS RCPTTY , NVL((SELECT SHORTX FROM DOCTM DT WHERE DT.DOCUTY = RH.RCPTTY), ' ') AS RCPTTYNM FROM RECDH RH INNER JOIN RECDI RI ON RI.RECVKY = RH.RECVKY INNER JOIN ASNDI AI ON AI.ASNDKY = RI.REFDKY AND AI.ASNDIT = RI.REFDIT INNER JOIN ASNDH AH ON AI.ASNDKY = AH.ASNDKY LEFT OUTER JOIN SKUMA SM ON SM.OWNRKY = RH.OWNRKY AND SM.SKUKEY = RI.SKUKEY LEFT OUTER JOIN BZPTN VD ON VD.OWNRKY = RH.OWNRKY AND VD.PTNRKY = RI.SKUG05 AND VD.PTNRTY = 'VD' WHERE 1 = 1 AND RH.WAREKY = #{WAREKY} AND RH.OWNRKY = #{OWNRKY} AND (RH.RCPTTY LIKE '11%' OR RH.RCPTTY LIKE '12%')
AND TRIM(RI.INDRCN) IS NULL
AND AH.ASNTTY = #{RCPTTY}
AND RI.REFDAT >= #{ASNDAT_FR} AND RI.REFDAT <= #{ASNDAT_TO}
AND RI.REFDAT = #{ASNDAT_FR}
AND RI.CREDAT >= #{CREDAT_FR} AND RI.CREDAT <= #{CREDAT_TO}
AND RI.CREDAT = #{CREDAT_FR}
${RANGE_SQL}
GROUP BY RI.REFDKY, RI.SEBELN, RI.STKNUM, RH.WAREKY , RH.OWNRKY, RH.DPTNKY, RH.RCPTTY

SELECT RH.RECVKY AS RECVKY , RI.RECVIT AS RECVIT , RI.REFDKY AS ASNDKY , RI.REFDIT AS ASNDIT , RI.SEBELN AS SEBELN , RI.SEBELP AS SEBELP , RI.STKNUM AS STKNUM , RI.STPNUM AS STPNUM , RI.SKUKEY AS SKUKEY , RI.DESC01 AS DESC01 , RI.DESC02 AS DESC02 , RI.LOCAKY AS LOCAKY , RI.TRNUID AS TRNUID , RI.QTYRCV AS QTYRCV , RI.UOMKEY AS UOMKEY , RI.MEASKY AS MEASKY , RI.LOTA10 AS LOTA10 , CASE WHEN TRIM(SM.ASKU01) = 'N' THEN '10000101' ELSE NVL(TRIM(RI.LOTA11), TO_CHAR(SYSDATE,'YYYYMMDD')) END AS LOTA11 , RI.LOTA12 AS LOTA12 , CASE WHEN TRIM(SM.ASKU01) = 'N' THEN '99991231' ELSE NVL(TRIM(RI.LOTA13), TO_CHAR(TO_DATE(NVL(TRIM(RI.LOTA11), TO_CHAR(SYSDATE,'YYYYMMDD')),'YYYYMMDD') + NVL(SM.QTYMON,1) - 1,'YYYYMMDD')) END AS LOTA13 , SM.ASKU01 AS ASKU01 , SM.QTYMON AS QTYMON , RI.INDRCN AS INDRCN , RI.CRECVD AS CRECVD , RI.RSNCOD AS RSNCOD , RI.RCPRSN AS RCPRSN , RI.CREDAT AS CREDAT , RI.CRETIM AS CRETIM , RI.CREUSR AS CREUSR , NVL((SELECT NMLAST FROM USRMA UR WHERE UR.USERID = RI.CREUSR),' ') AS CUSRNM , RI.LMODAT AS LMODAT , RI.LMOTIM AS LMOTIM , RI.LMOUSR AS LMOUSR , NVL((SELECT NMLAST FROM USRMA UR WHERE UR.USERID = RI.LMOUSR),' ') AS LUSRNM , RI.INDRCN AS INDRCN , RI.PRCRSN AS PRCRSN , RI.PRCRST AS PRCRST , CASE WHEN TRIM(MI.INDBZL) IS NULL THEN 'N' ELSE 'Y' END AS FISRCV , RI.INVCNO AS INVCNO , AD.BCDIND , SM.EANCOD AS EANCOD FROM RECDH RH INNER JOIN RECDI RI ON RH.RECVKY = RI.RECVKY LEFT OUTER JOIN SKUMA SM ON SM.OWNRKY = RH.OWNRKY AND SM.SKUKEY = RI.SKUKEY LEFT OUTER JOIN ASNDI AD ON AD.ASNDKY = RI.REFDKY AND AD.ASNDIT = RI.REFDIT LEFT OUTER JOIN SKUWC SW ON SW.WAREKY = RH.WAREKY AND SW.OWNRKY = RH.OWNRKY AND SW.SKUKEY = RI.SKUKEY LEFT OUTER JOIN BZPTN VD ON VD.OWNRKY = RH.OWNRKY AND VD.PTNRKY = RI.SKUG05 AND VD.PTNRTY = 'VD' LEFT OUTER JOIN MEASI MI ON MI.WAREKY = RH.WAREKY AND MI.MEASKY = SW.MEASKY AND MI.UOMKEY = SM.DUOMKY WHERE 1 = 1 AND RH.WAREKY = #{WAREKY} AND (RH.RCPTTY LIKE '11%' OR RH.RCPTTY LIKE '12%') AND TRIM(RI.INDRCN) IS NULL
AND RI.REFDKY = #{ASNDKY}
${RANGE_SQL}
ORDER BY RI.RECVKY, RI.RECVIT

mapper.update:
	   UPDATE RECDI
          SET STATIT = 'FCN'
            , INDRCN = 'V'
            , CRECVD = TO_CHAR(SYSDATE,'YYYYMMDD')

		     , RSNCOD = #{RSNCOD} 
		     , RCPRSN = #{RCPRSN} 

	    WHERE 1 = 1
	      AND RECVKY = #{RECVKY}
	      AND RECVIT = #{RECVIT}

	   UPDATE RECDH
          SET STATDO = 'FCN'
            , INDRCN = 'V'
            , CRECVD = TO_CHAR(SYSDATE,'YYYYMMDD')

		     , RSNCOD = #{RSNCOD} 
		     , RCPRSN = #{RCPRSN} 

	    WHERE 1 = 1
	      AND RECVKY = #{RECVKY}

mapper.select:
SELECT RH.WAREKY AS WAREKY , NVL((SELECT NAME01 FROM WAHMA WH WHERE WH.WAREKY = RH.WAREKY), ' ') AS WAREKYNM , RH.OWNRKY AS OWNRKY , NVL((SELECT NAME01 FROM OWNER NM WHERE NM.COMPKY = RH.OWNRKY),' ') AS OWNRKYNM , RH.DOCDAT , RH.DPTNKY AS DPTNKY , NVL((SELECT NAME01 FROM BZPTN BZ WHERE BZ.OWNRKY = RH.OWNRKY AND BZ.PTNRKY = RH.DPTNKY AND BZ.PTNRTY = 'VD'), ' ') AS DPTNKYNM , RH.RCPTTY AS RCPTTY , NVL((SELECT SHORTX FROM DOCTM DT WHERE DT.DOCUTY = RH.RCPTTY), ' ') AS RCPTTYNM , RH.DOCTXT AS DOCTXT , RH.CREDAT AS CREDAT , RH.CRETIM AS CRETIM , RH.CREUSR AS CREUSR , NVL((SELECT NMLAST FROM USRMA UR WHERE UR.USERID = RH.CREUSR),' ') AS CUSRNM , RH.LMODAT AS LMODAT , RH.LMOTIM AS LMOTIM , RH.LMOUSR AS LMOUSR , NVL((SELECT NMLAST FROM USRMA UR WHERE UR.USERID = RH.LMOUSR),' ') AS LUSRNM , RH.RECVKY AS RECVKY , RI.RECVIT AS RECVIT , RI.REFDKY AS ASNDKY , RI.REFDIT AS ASNDIT , RI.SEBELN AS SEBELN , RI.SEBELP AS SEBELP , RI.STKNUM AS STKNUM , RI.STPNUM AS STPNUM , RI.SKUKEY AS SKUKEY , RI.DESC01 AS DESC01 , RI.DESC02 AS DESC02 , RI.LOCAKY AS LOCAKY , RI.TRNUID AS TRNUID , RI.QTYRCV AS QTYRCV , RI.UOMKEY AS UOMKEY , RI.MEASKY AS MEASKY , RI.LOTA10 AS LOTA10 , CASE WHEN TRIM(SM.ASKU01) = 'N' THEN '10000101' ELSE NVL(TRIM(RI.LOTA11), TO_CHAR(SYSDATE,'YYYYMMDD')) END AS LOTA11 , RI.LOTA12 AS LOTA12 , CASE WHEN TRIM(SM.ASKU01) = 'N' THEN '99991231' ELSE NVL(TRIM(RI.LOTA13), TO_CHAR(TO_DATE(NVL(TRIM(RI.LOTA11), TO_CHAR(SYSDATE,'YYYYMMDD')),'YYYYMMDD') + NVL(SM.QTYMON,1) - 1,'YYYYMMDD')) END AS LOTA13 , RI.INDRCN AS INDRCN , RI.CRECVD AS CRECVD , RI.RSNCOD AS RSNCOD , RI.RCPRSN AS RCPRSN , RI.INDRCN AS INDRCN , RI.INVCNO AS INVCNO , RH.INSPTY AS INSPTY , RH.VEHINO AS VEHINO , RH.DRELIN AS DRELIN , RI.PRCRSN AS PRCRSN , RI.PRCRST AS PRCRST , CASE WHEN TRIM(MI.INDBZL) IS NULL THEN 'N' ELSE 'Y' END AS FISRCV , AD.BCDIND AS BCDIND , SM.ASKU01 AS ASKU01 , RI.REFDAT AS REFDAT , NVL((SELECT MS.QTPUOM FROM MEASI MS WHERE MS.WAREKY = RH.WAREKY AND MS.MEASKY = SW.MEASKY AND MS.UOMKEY = 'BOX'), 1) AS QTPUOM , SW.PLOCOV , SM.SKUG05 AS SELLER , NVL(SL.NAME01,'NOT EXISTS SELLER') AS SELLERNM , CASE WHEN RH.RCPTTY = '121' THEN RH.DPTNKY ELSE ' ' END AS WAREFR , CASE WHEN RH.RCPTTY = '121' THEN NVL(VD.NAME01,'NOT EXISTS SELLER') ELSE ' ' END AS WAREFRNM , AH.DELVCO AS DELVCO , AD.QTYASN AS QTYASN , SM.QTYMON , SM.EANCOD AS EANCOD FROM RECDH RH INNER JOIN RECDI RI ON RI.RECVKY = RH.RECVKY LEFT OUTER JOIN SKUMA SM ON SM.OWNRKY = RH.OWNRKY AND SM.SKUKEY = RI.SKUKEY LEFT OUTER JOIN ASNDI AD ON AD.ASNDKY = RI.REFDKY AND AD.ASNDIT = RI.REFDIT LEFT OUTER JOIN SKUWC SW ON SW.WAREKY = RH.WAREKY AND SW.OWNRKY = RH.OWNRKY AND SW.SKUKEY = RI.SKUKEY LEFT OUTER JOIN BZPTN VD ON VD.OWNRKY = RH.OWNRKY AND VD.PTNRKY = RH.DPTNKY AND VD.PTNRTY = 'VD' LEFT OUTER JOIN BZPTN SL ON SL.OWNRKY = RH.OWNRKY AND SL.PTNRKY = SM.SKUG05 AND SL.PTNRTY = 'VD' LEFT OUTER JOIN ASNDH AH ON AH.ASNDKY = AD.ASNDKY LEFT OUTER JOIN MEASI MI ON MI.WAREKY = RH.WAREKY AND MI.MEASKY = SW.MEASKY AND MI.UOMKEY = SM.DUOMKY WHERE 1 = 1 AND RH.WAREKY = #{WAREKY} AND RH.OWNRKY = #{OWNRKY} AND (RH.RCPTTY LIKE '11%' OR RH.RCPTTY LIKE '12%')
${RANGE_SQL}
AND TRIM(RI.INDRCN) IS NULL
AND TRIM(RI.INDRCN) IS NOT NULL
AND RI.REFDAT >= #{ASNDAT_FR} AND RI.REFDAT <= #{ASNDAT_TO}
AND RI.REFDAT = #{ASNDAT_FR}
AND RI.LOTA11 >= #{LOTA11_FR} AND RI.LOTA11 <= #{LOTA11_TO}
AND RI.LOTA11 = #{LOTA11_FR}
AND RI.LOTA12 >= #{LOTA12_FR} AND RI.LOTA12 <= #{LOTA12_TO}
AND RI.LOTA12 = #{LOTA12_FR}
AND RI.LOTA13 >= #{LOTA13_FR} AND RI.LOTA13 <= #{LOTA13_TO}
AND RI.LOTA13 = #{LOTA13_FR}

SELECT RI.REFDKY AS ASNDKY , RI.SEBELN AS SEBELN , RI.STKNUM AS STKNUM , RH.WAREKY AS WAREKY , NVL((SELECT NAME01 FROM WAHMA WH WHERE WH.WAREKY = RH.WAREKY), ' ') AS WAREKYNM , RH.OWNRKY AS OWNRKY , NVL((SELECT NAME01 FROM OWNER NM WHERE NM.COMPKY = RH.OWNRKY),' ') AS OWNRKYNM , RH.DPTNKY AS DPTNKY , NVL((SELECT NAME01 FROM BZPTN BZ WHERE BZ.OWNRKY = RH.OWNRKY AND BZ.PTNRKY = RH.DPTNKY AND BZ.PTNRTY = 'VD'), ' ') AS DPTNKYNM , RH.RCPTTY AS RCPTTY , NVL((SELECT SHORTX FROM DOCTM DT WHERE DT.DOCUTY = RH.RCPTTY), ' ') AS RCPTTYNM , RI.SVBELN AS SVBELN , RI.SPOSNR AS SPOSNR FROM RECDH RH INNER JOIN RECDI RI ON RI.RECVKY = RH.RECVKY LEFT OUTER JOIN SKUMA SM ON SM.OWNRKY = RH.OWNRKY AND SM.SKUKEY = RI.SKUKEY LEFT OUTER JOIN BZPTN VD ON VD.OWNRKY = RH.OWNRKY AND VD.PTNRKY = RI.SKUG05 AND VD.PTNRTY = 'VD' LEFT OUTER JOIN ASNDI AD ON AD.ASNDKY = RI.REFDKY AND AD.ASNDIT = RI.REFDIT LEFT OUTER JOIN ASNDH AH ON AH.ASNDKY = AD.ASNDKY WHERE 1 = 1 AND RH.WAREKY = #{WAREKY} AND RH.OWNRKY = #{OWNRKY} AND (RH.RCPTTY LIKE '13%') AND RI.STATIT IN ('NEW') AND TRIM(RI.INDRCN) IS NULL
AND RH.RCPTTY = #{RCPTTY}
AND RI.REFDAT >= #{REFDAT_FR} AND RI.REFDAT <= #{REFDAT_TO}
AND RI.REFDAT = #{REFDAT_FR}
AND RI.CREDAT >= #{CREDAT_FR} AND RI.CREDAT <= #{CREDAT_TO}
AND RI.CREDAT = #{CREDAT_FR}
${RANGE_SQL}
GROUP BY RI.REFDKY, RI.SEBELN, RI.STKNUM, RH.WAREKY , RH.OWNRKY, RH.DPTNKY, RH.RCPTTY, RI.SVBELN , RI.SPOSNR ORDER BY RI.REFDKY

SELECT RH.RECVKY AS RECVKY , RI.RECVIT AS RECVIT , RI.REFDKY AS ASNDKY , RI.REFDIT AS ASNDIT , RI.SEBELN AS SEBELN , RI.SEBELP AS SEBELP , RI.STKNUM AS STKNUM , RI.STPNUM AS STPNUM , RI.SKUKEY AS SKUKEY , RI.DESC01 AS DESC01 , RI.DESC02 AS DESC02 , RI.LOCAKY AS LOCAKY , RI.TRNUID AS TRNUID , RI.QTYRCV AS QTYRCV , RI.UOMKEY AS UOMKEY , RI.MEASKY AS MEASKY , RI.LOTA10 AS LOTA10 , CASE WHEN TRIM(SM.ASKU01) = 'N' THEN '10000101' ELSE RI.LOTA11 END AS LOTA11 , RI.LOTA12 AS LOTA12 , CASE WHEN TRIM(SM.ASKU01) = 'N' THEN '99991231' ELSE RI.LOTA13 END AS LOTA13 , SM.QTYMON , SM.ASKU01 , RI.INDRCN AS INDRCN , RI.CRECVD AS CRECVD , RI.RSNCOD AS RSNCOD , RI.RCPRSN AS RCPRSN , RI.CREDAT AS CREDAT , RI.CRETIM AS CRETIM , RI.CREUSR AS CREUSR , NVL((SELECT NMLAST FROM USRMA UR WHERE UR.USERID = RI.CREUSR),' ') AS CUSRNM , RI.LMODAT AS LMODAT , RI.LMOTIM AS LMOTIM , RI.LMOUSR AS LMOUSR , NVL((SELECT NMLAST FROM USRMA UR WHERE UR.USERID = RI.LMOUSR),' ') AS LUSRNM , RI.INDRCN AS INDRCN , RI.INVCNO AS INVCNO , RI.OINVNO AS OINVNO , RI.PRCRSN AS PRCRSN , RI.PRCRST AS PRCRST , CASE WHEN TRIM(MI.INDBZL) IS NULL THEN 'N' ELSE 'Y' END AS FISRCV , RI.INVCNO AS INVCNO , AD.BCDIND AS BCDIND , RI.SKUG05 AS SKUG05 , VD.NAME01 AS SKUG05NM , SM.EANCOD AS EANCOD FROM RECDH RH INNER JOIN RECDI RI ON RH.RECVKY = RI.RECVKY LEFT OUTER JOIN SKUMA SM ON SM.OWNRKY = RH.OWNRKY AND SM.SKUKEY = RI.SKUKEY LEFT OUTER JOIN SKUWC SW ON SW.WAREKY = RH.WAREKY AND SW.OWNRKY = RH.OWNRKY AND SW.SKUKEY = RI.SKUKEY LEFT OUTER JOIN ASNDI AD ON AD.ASNDKY = RI.REFDKY AND AD.ASNDIT = RI.REFDIT LEFT OUTER JOIN BZPTN VD ON VD.OWNRKY = RH.OWNRKY AND VD.PTNRKY = RI.SKUG05 AND VD.PTNRTY = 'VD' LEFT OUTER JOIN MEASI MI ON MI.WAREKY = RH.WAREKY AND MI.MEASKY = SW.MEASKY AND MI.UOMKEY = SM.DUOMKY WHERE 1 = 1 AND RH.WAREKY = #{WAREKY} AND (RH.RCPTTY LIKE '13%') AND RI.STATIT IN ('NEW') AND TRIM(RI.INDRCN) IS NULL
AND RI.REFDKY = #{ASNDKY}
${RANGE_SQL}
ORDER BY RI.RECVKY, RI.RECVIT

mapper.update:
	   UPDATE RECDI
          SET STATIT = 'FCN'
            , INDRCN = 'V'
            , CRECVD = TO_CHAR(SYSDATE,'YYYYMMDD')
           	, RSNCOD = #{RSNCOD}

       	 	, RCPRSN = #{RCPRSN}

	    WHERE 1 = 1
	      AND RECVKY = #{RECVKY}
	      AND RECVIT = #{RECVIT}

	   UPDATE RECDH
          SET STATDO = 'FCN'
            , INDRCN = 'V'
            , CRECVD = TO_CHAR(SYSDATE,'YYYYMMDD')
           	, RSNCOD = #{RSNCOD}

       	 	, RCPRSN = #{RCPRSN}

	    WHERE 1 = 1
	      AND RECVKY = #{RECVKY}

mapper.select:
SELECT RH.WAREKY AS WAREKY , NVL((SELECT NAME01 FROM WAHMA WH WHERE WH.WAREKY = RH.WAREKY), ' ') AS WAREKYNM , RH.OWNRKY AS OWNRKY , NVL((SELECT NAME01 FROM OWNER NM WHERE NM.COMPKY = RH.OWNRKY),' ') AS OWNRKYNM , RH.DOCDAT , RH.DPTNKY AS DPTNKY , NVL((SELECT NAME01 FROM BZPTN BZ WHERE BZ.OWNRKY = RH.OWNRKY AND BZ.PTNRKY = RH.DPTNKY AND BZ.PTNRTY = 'VD'), ' ') AS DPTNKYNM , RH.RCPTTY AS RCPTTY , NVL((SELECT SHORTX FROM DOCTM DT WHERE DT.DOCUTY = RH.RCPTTY), ' ') AS RCPTTYNM , RH.DOCTXT AS DOCTXT , RH.CREDAT AS CREDAT , RH.CRETIM AS CRETIM , RH.CREUSR AS CREUSR , NVL((SELECT NMLAST FROM USRMA UR WHERE UR.USERID = RH.CREUSR),' ') AS CUSRNM , RH.LMODAT AS LMODAT , RH.LMOTIM AS LMOTIM , RH.LMOUSR AS LMOUSR , NVL((SELECT NMLAST FROM USRMA UR WHERE UR.USERID = RH.LMOUSR),' ') AS LUSRNM , RH.RECVKY AS RECVKY , RI.RECVIT AS RECVIT , RI.REFDKY AS ASNDKY , RI.REFDIT AS ASNDIT , RI.SEBELN AS SEBELN , RI.SEBELP AS SEBELP , RI.STKNUM AS STKNUM , RI.STPNUM AS STPNUM , RI.SKUKEY AS SKUKEY , RI.DESC01 AS DESC01 , RI.DESC02 AS DESC02 , RI.LOCAKY AS LOCAKY , RI.TRNUID AS TRNUID , RI.QTYRCV AS QTYRCV , RI.UOMKEY AS UOMKEY , RI.MEASKY AS MEASKY , RI.LOTA10 AS LOTA10 , CASE WHEN TRIM(SM.ASKU01) = 'N' THEN '10000101' ELSE RI.LOTA11 END AS LOTA11 , RI.LOTA12 AS LOTA12 , CASE WHEN TRIM(SM.ASKU01) = 'N' THEN '99991231' ELSE RI.LOTA13 END AS LOTA13 , RI.INDRCN AS INDRCN , RI.CRECVD AS CRECVD , RI.RSNCOD AS RSNCOD , RI.RCPRSN AS RCPRSN , RI.INDRCN AS INDRCN , RI.INVCNO AS INVCNO , RI.OINVNO AS OINVNO , RH.INSPTY AS INSPTY , RH.VEHINO AS VEHINO , RH.DRELIN AS DRELIN , RI.PRCRSN AS PRCRSN , RI.PRCRST AS PRCRST , CASE WHEN TRIM(MI.INDBZL) IS NULL THEN 'N' ELSE 'Y' END AS FISRCV , AD.BCDIND AS BCDIND , RI.SKUG05 , VD.NAME01 AS SKUG05NM , RI.SVBELN AS SVBELN , RI.SPOSNR AS SPOSNR , RI.STRAID AS STRAID , AH.RCVNAM , AH.CLMRSN , AH.DLVETY , AD.QTYASN , NVL((SELECT MS.QTPUOM FROM MEASI MS WHERE MS.WAREKY = RH.WAREKY AND MS.MEASKY = RI.SKUKEY AND MS.UOMKEY = 'BOX'), 1) AS QTPUOM , SM.ASKU01 , SM.QTYMON , RI.REFDAT , SM.EANCOD FROM RECDH RH INNER JOIN RECDI RI ON RI.RECVKY = RH.RECVKY LEFT OUTER JOIN SKUMA SM ON SM.OWNRKY = RH.OWNRKY AND SM.SKUKEY = RI.SKUKEY LEFT OUTER JOIN SKUWC SW ON SW.WAREKY = RH.WAREKY AND SW.OWNRKY = RH.OWNRKY AND SW.SKUKEY = RI.SKUKEY LEFT OUTER JOIN ASNDI AD ON AD.ASNDKY = RI.REFDKY AND AD.ASNDIT = RI.REFDIT LEFT OUTER JOIN BZPTN VD ON VD.OWNRKY = RH.OWNRKY AND VD.PTNRKY = RI.SKUG05 AND VD.PTNRTY = 'VD' LEFT OUTER JOIN ASNDH AH ON AH.ASNDKY = AD.ASNDKY LEFT OUTER JOIN MEASI MI ON MI.WAREKY = RH.WAREKY AND MI.MEASKY = SW.MEASKY AND MI.UOMKEY = SM.DUOMKY WHERE 1 = 1 AND RH.WAREKY = #{WAREKY} AND RH.OWNRKY = #{OWNRKY}
AND RH.RCPTTY = #{RCPTTY}
AND (RH.RCPTTY LIKE '13%')
${RANGE_SQL}
AND TRIM(RI.INDRCN) IS NULL
AND TRIM(RI.INDRCN) IS NOT NULL
AND RI.REFDAT >= #{REFDAT_FR} AND RI.REFDAT <= #{REFDAT_TO}
AND RI.REFDAT = #{REFDAT_FR}
AND RI.LOTA12 >= #{LOTA12_FR} AND RI.LOTA12 <= #{LOTA12_TO}
AND RI.LOTA12 = #{LOTA12_FR}

SELECT AH.ASNDKY , AI.SEBELN , AI.STKNUM , AH.STATDO , NVL((SELECT CDESC1 FROM CMCDV WHERE CMCDKY = 'STATDO' AND CMCDVL = AH.STATDO),' ') AS STATDONM , AH.WAREKY , NVL((SELECT NAME01 FROM WAHMA WHERE WAREKY = AH.WAREKY),' ') AS WARENM , AH.OWNRKY , NVL((SELECT NAME01 FROM OWNER WHERE OWNRKY = AH.OWNRKY),' ') AS OWNRNM , AH.ASNTTY AS RCPTTY , NVL((SELECT SHORTX FROM DOCTM WHERE DOCUTY = AH.ASNTTY),' ') AS RCPTNM , AH.ASNDAT , TO_CHAR(SYSDATE,'YYYYMMDD') AS DOCDAT , AH.DPTNKY , NVL(VD.NAME01,'NOT EXISTS SELLER') AS DPTNNM , AH.CARTYP , AH.DELVCO , AH.VEHINO , CASE WHEN TRIM(AI.VEHDAT) IS NULL OR AI.VEHDAT = '00000000' THEN ' ' ELSE 'V' END AS UNLOAD , AH.DOCTXT , CASE WHEN VD.PTNRKY IS NULL THEN '존재하지 않는 SELLER 마스터 입니다.' WHEN TRIM(VD.PROCHA) IS NOT NULL THEN '입고불허된 SELLER 입니다.' WHEN TRIM(VD.DELMAK) IS NOT NULL THEN '마스터 삭제된 SELLER 입니다.' END RSTTXT , AI.VEHDAT , AI.VEHTIM , VE.VEHINM , VE.VEHIOW , VE.VEHITY , VE.VEHIWG , VE.DRIVER , VE.TELN01 , VE.VEHSTS , AH.DRELIN , AI.INVCNO FROM ASNDH AH INNER JOIN ASNDI AI ON AI.ASNDKY = AH.ASNDKY LEFT OUTER JOIN SKUMA SM ON SM.OWNRKY = AH.OWNRKY AND SM.SKUKEY = AI.SKUKEY LEFT OUTER JOIN SKUWC SW ON SW.WAREKY = AH.WAREKY AND SW.OWNRKY = AH.OWNRKY AND SW.SKUKEY = AI.SKUKEY LEFT OUTER JOIN BZPTN VD ON VD.OWNRKY = AH.OWNRKY AND VD.PTNRKY = SM.SKUG05 AND VD.PTNRTY = 'VD' LEFT OUTER JOIN MEASI MI ON MI.WAREKY = AH.WAREKY AND MI.MEASKY = SW.MEASKY AND MI.UOMKEY = SM.DUOMKY LEFT OUTER JOIN VEHMA VE ON VE.VEHINO = AH.VEHINO WHERE AH.WAREKY = #{WAREKY} AND AH.OWNRKY = #{OWNRKY}
AND AH.ASNTTY = #{RCPTTY}
AND AH.DRELIN = #{DRELIN}
AND TRIM(AH.DELMAK) IS NULL AND AI.QTYASN - AI.QTYRCV > 0 AND AI.STATIT = 'NEW'
${RANGE_SQL}
GROUP BY AH.ASNDKY , AI.SEBELN , AI.STKNUM , AI.VEHDAT , AH.STATDO , AH.WAREKY , AH.OWNRKY , AH.ASNTTY , AH.ASNDAT , AH.DPTNKY , NVL(VD.NAME01,'NOT EXISTS SELLER') , AH.CARTYP , AH.DELVCO , AH.VEHINO , AH.DOCTXT , VD.PTNRKY , TRIM(VD.PROCHA) , TRIM(VD.DELMAK) , AI.VEHDAT , AI.VEHTIM , AH.VEHINO , VE.VEHINM , VE.VEHIOW , VE.VEHITY , VE.VEHIWG , VE.DRIVER , VE.TELN01 , VE.VEHSTS , AH.DRELIN , AI.INVCNO

